func TestEpochTraceJson(t *testing.T) {
	v := `{"cfxTraces":[{"action":{"from":"cfx:aat0jttuwbs23e9jfms662s96u7z8hw2ce2ybk800c","fromPocket":"balance","fromSpace":"native","to":"cfx:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa0sfbnjm2","toPocket":"gas_payment","toSpace":"none","value":"0x76aa"},"blockHash":"0xf96d3af4f5d65e9d81057b5b85cfd1dd6f8fec966f0263fe80afedc85c31be4d","epochHash":"0xf96d3af4f5d65e9d81057b5b85cfd1dd6f8fec966f0263fe80afedc85c31be4d","epochNumber":"0xd2fe5","transactionHash":"0x57602606aa7cb0e823d555b52bbaafae89c559107c7106eeaa0bf14cf8dbee88","transactionPosition":"0x0","type":"internal_transfer_action","valid":true},{"action":{"callType":"call","from":"cfx:aat0jttuwbs23e9jfms662s96u7z8hw2ce2ybk800c","gas":"0x1e52","input":"0x00f55d9d00000000000000000000000080adc527a83a9042d8b93c9a54dde9af6e93422d","space":"native","to":"cfx:aaejuaaaaaaaaaaaaaaaaaaaaaaaaaaaaa2mhjju8k","value":"0x0"},"blockHash":"0xf96d3af4f5d65e9d81057b5b85cfd1dd6f8fec966f0263fe80afedc85c31be4d","epochHash":"0xf96d3af4f5d65e9d81057b5b85cfd1dd6f8fec966f0263fe80afedc85c31be4d","epochNumber":"0xd2fe5","transactionHash":"0x57602606aa7cb0e823d555b52bbaafae89c559107c7106eeaa0bf14cf8dbee88","transactionPosition":"0x0","type":"call","valid":true},{"action":{"from":"cfx:acam5vkhza7kau021e8kyzg77g107e4cfy9w63gw24","fromPocket":"balance","fromSpace":"native","to":"cfx:aat0jttuwbs23e9jfms662s96u7z8hw2ce2ybk800c","toPocket":"balance","toSpace":"native","value":"0x0"},"blockHash":"0xf96d3af4f5d65e9d81057b5b85cfd1dd6f8fec966f0263fe80afedc85c31be4d","epochHash":"0xf96d3af4f5d65e9d81057b5b85cfd1dd6f8fec966f0263fe80afedc85c31be4d","epochNumber":"0xd2fe5","transactionHash":"0x57602606aa7cb0e823d555b52bbaafae89c559107c7106eeaa0bf14cf8dbee88","transactionPosition":"0x0","type":"internal_transfer_action","valid":true},{"action":{"gasLeft":"0xaca","outcome":"success","returnData":"0x"},"blockHash":"0xf96d3af4f5d65e9d81057b5b85cfd1dd6f8fec966f0263fe80afedc85c31be4d","epochHash":"0xf96d3af4f5d65e9d81057b5b85cfd1dd6f8fec966f0263fe80afedc85c31be4d","epochNumber":"0xd2fe5","transactionHash":"0x57602606aa7cb0e823d555b52bbaafae89c559107c7106eeaa0bf14cf8dbee88","transactionPosition":"0x0","type":"call_result","valid":true},{"action":{"from":"cfx:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa0sfbnjm2","fromPocket":"gas_payment","fromSpace":"none","to":"cfx:aat0jttuwbs23e9jfms662s96u7z8hw2ce2ybk800c","toPocket":"balance","toSpace":"native","value":"0xaca"},"blockHash":"0xf96d3af4f5d65e9d81057b5b85cfd1dd6f8fec966f0263fe80afedc85c31be4d","epochHash":"0xf96d3af4f5d65e9d81057b5b85cfd1dd6f8fec966f0263fe80afedc85c31be4d","epochNumber":"0xd2fe5","transactionHash":"0x57602606aa7cb0e823d555b52bbaafae89c559107c7106eeaa0bf14cf8dbee88","transactionPosition":"0x0","type":"internal_transfer_action","valid":true},{"action":{"from":"cfx:aat0jttuwbs23e9jfms662s96u7z8hw2ce2ybk800c","fromPocket":"storage_collateral","fromSpace":"native","to":"cfx:aat0jttuwbs23e9jfms662s96u7z8hw2ce2ybk800c","toPocket":"balance","toSpace":"native","value":"0x6f05b59d3b20000"},"blockHash":"0xf96d3af4f5d65e9d81057b5b85cfd1dd6f8fec966f0263fe80afedc85c31be4d","epochHash":"0xf96d3af4f5d65e9d81057b5b85cfd1dd6f8fec966f0263fe80afedc85c31be4d","epochNumber":"0xd2fe5","transactionHash":"0x57602606aa7cb0e823d555b52bbaafae89c559107c7106eeaa0bf14cf8dbee88","transactionPosition":"0x0","type":"internal_transfer_action","valid":true},{"action":{"from":"cfx:acam5vkhza7kau021e8kyzg77g107e4cfy9w63gw24","fromPocket":"staking_balance","fromSpace":"native","to":"cfx:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa0sfbnjm2","toPocket":"mint_or_burn","toSpace":"none","value":"0x0"},"blockHash":"0xf96d3af4f5d65e9d81057b5b85cfd1dd6f8fec966f0263fe80afedc85c31be4d","epochHash":"0xf96d3af4f5d65e9d81057b5b85cfd1dd6f8fec966f0263fe80afedc85c31be4d","epochNumber":"0xd2fe5","transactionHash":"0x57602606aa7cb0e823d555b52bbaafae89c559107c7106eeaa0bf14cf8dbee88","transactionPosition":"0x0","type":"internal_transfer_action","valid":true},{"action":{"from":"cfx:acam5vkhza7kau021e8kyzg77g107e4cfy9w63gw24","fromPocket":"balance","fromSpace":"native","to":"cfx:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa0sfbnjm2","toPocket":"mint_or_burn","toSpace":"none","value":"0x0"},"blockHash":"0xf96d3af4f5d65e9d81057b5b85cfd1dd6f8fec966f0263fe80afedc85c31be4d","epochHash":"0xf96d3af4f5d65e9d81057b5b85cfd1dd6f8fec966f0263fe80afedc85c31be4d","epochNumber":"0xd2fe5","transactionHash":"0x57602606aa7cb0e823d555b52bbaafae89c559107c7106eeaa0bf14cf8dbee88","transactionPosition":"0x0","type":"internal_transfer_action","valid":true}],"ethTraces":[],"mirrorAddressMap":{}}`
	var e EpochTrace
	err := utils.JsonUnmarshal([]byte(v), &e)
	assert.NoError(t, err, v)

	output, err := utils.JsonMarshal(e)
	assert.NoError(t, err, v)

	assert.Equal(t, utils.FormatJson(v), utils.FormatJson(string(output)))
}
